\begin{tikzpicture}[x=9mm,y=9mm,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{seriesBlue}{HTML}{268CFF}\definecolor{seriesRed}{HTML}{EF6068}\definecolor{seriesGreen}{HTML}{4F9B63}\definecolor{seriesPurple}{HTML}{8B5CC7}
\draw[->,line width=.5pt] (-4.5,0)--(4.7,0) node[right] {$x$};\draw[->,line width=.5pt] (0,-4.5)--(0,4.7) node[above] {$y$};
\begin{scope}\clip (-4.3,-4.3) rectangle (4.3,4.3);
\foreach \lo/\hi in {-4.2/-.2,.2/4.2}{
\draw[seriesBlue,line width=.8pt,domain=\lo:\hi,samples=130] plot (\x,{1/\x});
\draw[seriesRed,dashed,line width=.8pt,domain=\lo:\hi,samples=130] plot (\x,{2/\x});
\draw[seriesGreen,dash dot,line width=.8pt,domain=\lo:\hi,samples=130] plot (\x,{-1/\x});
\draw[seriesPurple,densely dotted,line width=.8pt,domain=\lo:\hi,samples=130] plot (\x,{-2/\x});}\end{scope}
\fill[seriesBlue] (1,1) circle (1pt) node[right,text=black] {$(1,1)$};\fill[seriesRed] (1,2) circle (1pt) node[right,text=black] {$(1,2)$};\fill[seriesGreen] (1,-1) circle (1pt) node[right,text=black] {$(1,-1)$};\fill[seriesPurple] (1,-2) circle (1pt) node[right,text=black] {$(1,-2)$};
\node[seriesBlue,right] at (4.5,2.6) {$y=f(x)$};\node[seriesRed,right] at (4.5,1.5) {$y=2f(x)$};\node[seriesGreen,right] at (4.5,-1.5) {$y=-f(x)$};\node[seriesPurple,right] at (4.5,-2.6) {$y=-2f(x)$};
\end{tikzpicture}
